int sctp_peeloff(struct sock *sk, sctp_assoc_t id, struct socket **sockp)
{
    int ret = -EINVAL;
    struct socket *new_sk = NULL;

    if (!sk || !sockp)
        return -EINVAL;

    if (id == 0)
        return -EINVAL;

    if (!sctp_assoc_exists(sk, id))
        return -ENOENT;

    if (sctp_has_pending_buffers(sk, id)) {
        return -EBUSY;
    }

    new_sk = sctp_create_new_socket();
    if (!new_sk) {
        return -ENOMEM;
    }

    if (sctp_copy_socket_props(sk, new_sk)) {
        ret = -EFAULT;
        goto error;
    }

    if (sctp_migrate_association(sk, id, new_sk)) {
        ret = -EFAULT;
        goto error;
    }

    *sockp = new_sk;
    return 0;

error:
    if (new_sk) {
        sctp_free_socket(new_sk);
    }
    return ret;
}
